// parent will pass: value (number), onChange(fn), max (optional)
import React from "react";

function RatingStars({ value = 0, onChange = () => {}, max = 5 }) {
  // TODO (later): render '★' up to `value` and '☆' for the rest.
  // on click: call onChange(n)
  // keep it placeholder-y for now.

  return (
    <div className="stars">
      {/* placeholder text so you remember to wire this up */}
      <span>Rating: {value}/{max}</span>
    </div>
  );
}

export default RatingStars;
